    ivec2 size=ivec2(uGrid), origin=nextCell-1;
    for(int j=0;j<4;j++) for(int i=0;i<4;i++) {
      vec3 h=texelFetch(uHeight,clamp(origin+ivec2(i,j),ivec2(0),size-1),0).rgb;
      heightPatch[j][i]=dot(h,vec3(1.,uCosine,uSine));
