  vec4 slopes=(3.*heightPatch[3]*f.x+2.*heightPatch[2])*f.x+heightPatch[1];
  vec3 result=vec3(dot(rows,y),dot(slopes,y),dot(rows,dy));
  result.yz*=vec2(uGrid.x-1.,-(uGrid.y-1.))/uExtent;
  return result;
}
`;

