      columns = Math.max(2, Math.ceil(width / cell)),
      rows = Math.max(2, Math.ceil(height / cell)),
      count = columns * rows,
      offset = ((((Math.round(config.seed) * 0.61803398875) % 1) + 1) % 1) * Math.PI * 2;
