    gradientCosines = new Float32Array(count);
    gradientSines = new Float32Array(count);
    for (let y = 0; y < rows; y++)
      for (let x = 0; x < columns; x++) {
        const px = (((x + 0.5) / columns) * width) / scale,
          py = (((y + 0.5) / rows) * height) / scale,
